	"errors"
	"fmt"
	"io/ioutil"
	"math"
	"os"
	"regexp"
	"strconv"
	"strings"
)

const MOD int64 = 998244353

func solve(read func() string) int64 {
	_, _, rns, _, _ := convertInput(read)
	nm := rns()
	n, m := nm[0], nm[1]
	pre := int64(1)
	M := mod(m)
	res := int64(0)
	ans := M
	ans1 := M
	p := getPrimes(n + 10)
	for i := int64(2); i <= n; i++ {
		if pre <= m && p[i] != 0 {
			pre = pre * i
		}
		if pre > m {
			ans = 0
		} else {
			ans = mul(ans, int64(math.Floor(float64(m)/float64(pre))))
		}
		ans1 = mul(ans1, M)
		res = mod(res + ans1 - ans)
	}
	return res
}

func getPrimes(n int64) []int64 {
	nums := make([]int64, n+1)
	for i := range nums {
		nums[i] = 1
	}
	nums[0] = 0
	if n >= 1 {
		nums[1] = 0
	}
	primes := []int64{}
	for i := int64(2); i <= n; i++ {
		if nums[i] != 0 {
			primes = append(primes, i)
		}
		for j := 0; j < len(primes) && primes[j]*i <= n; j++ {
			nums[primes[j]*i] = 0
			if i%primes[j] == 0 {
				break
			}
		}
	}
	return nums
}

func mod(num int64) int64 {
	if num >= MOD {
		return num % MOD
	} else if num < 0 {
		return (num%MOD + MOD) % MOD
	}
	return num
}

func mul(args ...int64) int64 {
	if len(args) == 0 {
		panic(errors.New("参数不能为空"))
	}
	if len(args) == 1 {
		return args[0]
	}
	a, b := args[0], args[1]
	if len(args) > 2 {
		rest := append([]int64{mul(a, b)}, args[2:]...)
		return mul(rest...)
	}
	return ((a/65536)*b%MOD*65536 + (a&65535)*b) % MOD
}

func convertInput(read func() string) (func() int64, func() int64, func() []int64, func() []int64, func() []int64) {
	rn := func() int64 {
		v, _ := strconv.ParseInt(strings.TrimSpace(read()), 10, 64)
		return v
	}
	rb := func() int64 {
		v, _ := strconv.ParseInt(strings.TrimSpace(read()), 10, 64)
		return v
	}
	rns := func() []int64 {
		parts := strings.Fields(read())
		res := make([]int64, len(parts))
		for i, s := range parts {
			v, _ := strconv.ParseInt(s, 10, 64)
			res[i] = v
		}
		return res
	}
	re := func() []int64 {
		parts := strings.Fields(read())
		res := make([]int64, len(parts))
		for i, s := range parts {
			v, _ := strconv.ParseInt(s, 10, 64)
			res[i] = v - 1
		}
		return res
	}
	rbs := func() []int64 {
		parts := strings.Fields(read())
		res := make([]int64, len(parts))
		for i, s := range parts {
			v, _ := strconv.ParseInt(s, 10, 64)
			res[i] = v
		}
		return res
	}
	return rn, rb, rns, re, rbs
}

func main() {
	data, _ := ioutil.ReadAll(os.Stdin)
	re := regexp.MustCompile(`\r?\n`)
	inputs := re.Split(string(data), -1)
	i := 0
	read := func() string {
		if i < len(inputs) {
			s := inputs[i]
			i++
			return s
		}
		i++
		return ""
	}
	t := 1
	res := make([]string, t)
	limit := 0
	for k := 0; k < t; k++ {
		s := solve(read)
		if t < limit {
		} else {
			res[k] = strconv.FormatInt(s, 10)
		}
	}
	if t >= limit {
		fmt.Print(strings.Join(res, "\n"))
	}
}
